#include <vector>

struct Animation { std::vector<float> durations; bool loop; };

class Animator
{
public:
    void play(const Animation* a)
    {
        if (a == m_anim) return;
        m_anim = a;
        m_frame = 0;
        m_inFrame = 0;
        m_started = false;
        m_finished = false;
    }

    std::vector<int> update(float dt)
    {
        std::vector<int> entered;
        if (!m_anim || m_anim->durations.empty() || m_finished) return entered;
        if (!m_started) { m_started = true; entered.push_back(0); }
        m_inFrame += dt;
        const int count{ static_cast<int>(m_anim->durations.size()) };
        while (m_inFrame >= m_anim->durations[static_cast<std::size_t>(m_frame)])
        {
            const float d{ m_anim->durations[static_cast<std::size_t>(m_frame)] };
            if (m_frame + 1 < count) { m_inFrame -= d; ++m_frame; entered.push_back(m_frame); }
            else if (m_anim->loop) { m_inFrame -= d; m_frame = 0; entered.push_back(0); }
            else { m_finished = true; break; }
            if (d <= 0) break;
        }
        return entered;
    }

    int frame() const { return m_frame; }
    bool finished() const { return m_finished; }

private:
    const Animation* m_anim{ nullptr };
    int m_frame{ 0 };
    float m_inFrame{ 0 };
    bool m_started{ false };
    bool m_finished{ false };
};

