using Frames = std::vector<int>;
const Animation walk{ { 0.1f, 0.2f, 0.1f }, true };
const Animation attack{ { 0.05f, 0.05f, 0.2f }, false };
TEST("frames by time") {
    Animator a; a.play(&walk);
    CHECK_EQ(a.update(0.05f), (Frames{ 0 })); CHECK_EQ(a.frame(), 0);
    CHECK_EQ(a.update(0.1f), (Frames{ 1 })); CHECK_EQ(a.frame(), 1);
    CHECK_EQ(a.update(0.2f), (Frames{ 2 })); CHECK_EQ(a.frame(), 2);
    CHECK_EQ(a.update(0.1f), (Frames{ 0 })); CHECK_EQ(a.frame(), 0);
}
TEST("a long frame wraps several times") { Animator a; a.play(&walk); CHECK_EQ(a.update(0.85f), (Frames{ 0, 1, 2, 0, 1, 2, 0 })); CHECK_EQ(a.frame(), 0); }
TEST("play again does not restart") { Animator a; a.play(&walk); a.update(0.15f); a.play(&walk); CHECK_EQ(a.frame(), 1); CHECK(a.update(0.01f).empty()); }
TEST("one-shot") {
    Animator a; a.play(&attack);
    CHECK_EQ(a.update(0.07f), (Frames{ 0, 1 })); CHECK(!a.finished());
    CHECK_EQ(a.update(0.1f), (Frames{ 2 })); CHECK(!a.finished());
    CHECK(a.update(0.5f).empty()); CHECK(a.finished()); CHECK_EQ(a.frame(), 2); CHECK(a.update(1.0f).empty());
}
TEST("switching restarts") { Animator a; a.play(&attack); a.update(1.0f); a.play(&walk); CHECK(!a.finished()); CHECK_EQ(a.frame(), 0); CHECK_EQ(a.update(0.0f), (Frames{ 0 })); }

